/*
Dynamic ropes

Uses a series of dynamic objects to create an interactive rope.

Author:
  Jason Labbe

Site:
  jasonlabbe3d.com
*/

var ropes = [];
var collisionSize;
var debugMode = false;

var gravitySlider;
var airDragSlider;
var elasticitySlider;
var thicknessSlider;
var collisionSizeSlider;
var debugButton;


function setup() {
  createCanvas(windowWidth, windowHeight);

  // Create on-screen controls.
  gravitySlider = new SliderLayout("Gravity", 0.5, 5, 2, 0.1, 100, 100);
  airDragSlider = new SliderLayout("Air drag", 0.1, 0.5, 0.2, 0.1, 100, 170);
  elasticitySlider = new SliderLayout("Elasticity", 0.05, 0.3, 0.1, 0.01, 100, 240);
  thicknessSlider = new SliderLayout("Stroke thickness", 1, 4, 2, 0.1, 100, 310);
  collisionSizeSlider = new SliderLayout("Collision size", 50, 150, 100, 1, 100, 380);
  debugButton = createButton("Toggle debug display");
  debugButton.position(100, collisionSizeSlider.slider.position().y+40);
  debugButton.mousePressed(debugButtonOnClick);

  var ropeCount = 100;

  // Create a series of ropes along the scene's width.
  for (var i = 0; i < ropeCount; i++) {
    var x = map(i, 0, ropeCount, width/2-200, width/2+200);
    var y = height/4;

    var newRope = new Rope(x, y, 10);
    ropes.push(newRope);
  }
} 


function draw() {
  background(75);

  collisionSize = collisionSizeSlider.slider.value();

  // Display collision object.
  noStroke();
  fill(255, 0, 0);
  ellipse((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), collisionSize*2, collisionSize*2);

  // React against collision object.
  for (var i = 0; i < ropes.length; i++) {
    for (var j = 0; j < ropes[i].objs.length; j++) {
      var d = dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), ropes[i].objs[j].pos.x, ropes[i].objs[j].pos.y);

      if (d < collisionSize) {
        // Push ball away from collision object.
        var force = new p5.Vector(ropes[i].objs[j].pos.x, ropes[i].objs[j].pos.y);
        force.sub((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
        force.normalize();
        force.mult(2);
        ropes[i].objs[j].acc.add(force);
      }
    }

    ropes[i].display();
  }

  // Display on-screen controls.
  gravitySlider.display();
  airDragSlider.display();
  elasticitySlider.display();
  thicknessSlider.display();
  collisionSizeSlider.display();
}


